describe('AC1.B / T3: Dogfood vendored proto code (Q6)', () => {
  test('1.5-UNIT-110: packages/proto/gen/go/he/sample/v1/sample.pb.go exists', () => {
    expect(repoFileExists('packages/proto/gen/go/he/sample/v1/sample.pb.go')).toBe(true);
  });

  test('1.5-UNIT-111: at least one *.connect.go file under gen/go/he/sample/v1/', () => {
    const dir = 'packages/proto/gen/go/he/sample/v1';
    if (!repoFileExists(dir)) {
      expect(false).toBe(true);
      return;
    }
    const allFiles: string[] = [];
    const walk = (rel: string): void => {
      for (const e of readdirSync(repoPath(rel))) {
        const full = join(rel, e);
        const s = statSync(repoPath(full));
        if (s.isDirectory()) walk(full);
        else allFiles.push(full);
      }
    };
    walk(dir);
    expect(allFiles.some((f) => f.endsWith('.connect.go'))).toBe(true);
  });

  test('1.5-UNIT-112: sample.pb.go is auto-generated', () => {
    expect(readRepoFile('packages/proto/gen/go/he/sample/v1/sample.pb.go')).toMatch(
      /Code generated|DO NOT EDIT/,
    );
  });

  test('1.5-UNIT-113: source proto file packages/proto/he/sample/v1/sample.proto exists', () => {
    expect(repoFileExists(SAMPLE_PROTO)).toBe(true);
  });
});

