describe('Cross-cutting: Architect Round 1/2 traceability invariants', () => {
  test('1.5-UNIT-220: Story body retains Q1-Q8 Rulings Traceability table', () => {
    expect(readRepoFile(STORY_FILE)).toMatch(/Q1-Q8 Rulings Traceability/);
  });

  test('1.5-UNIT-221: Change Log contains Created / RequiresRevision / Round 2 transitions', () => {
    const src = readRepoFile(STORY_FILE);
    expect(src).toMatch(/Created/);
    expect(src).toMatch(/RequiresRevision/);
    expect(src).toMatch(/Round 2/);
  });

  test('1.5-UNIT-222: all .tmpl deliverables collectively reference {{NAME}} AND {{DOMAIN}} tokens', () => {
    if (!repoFileExists(TPL_ROOT)) {
      expect(false).toBe(true);
      return;
    }
    const allTmpl: string[] = [];
    const walk = (rel: string): void => {
      for (const e of readdirSync(repoPath(rel))) {
        const full = join(rel, e);
        const s = statSync(repoPath(full));
        if (s.isDirectory()) walk(full);
        else if (full.endsWith('.tmpl')) allTmpl.push(full);
      }
    };
    walk(TPL_ROOT);
    const allSrc = allTmpl.map((f) => readRepoFile(f)).join('\n');
    expect(allSrc).toMatch(/\{\{NAME\}\}|\$\{NAME\}/);
    expect(allSrc).toMatch(/\{\{DOMAIN\}\}|\$\{DOMAIN\}/);
  });
});

